import { Suspense } from 'react';
import Link from 'next/link';
import TopAppBar from '@/components/TopAppBar';
import SearchFilters from '@/components/SearchFilters';
import { getProperties } from '@/lib/api/properties';
import type { PropertyRecord } from '@/app/actions/property';
import { userSummary, quickActions } from '@/lib/data/dashboard';

interface DashboardPageProps {
  searchParams: Promise<{ location?: string; minPrice?: string; maxPrice?: string }>;
}

function PropertyCard({ property }: { property: PropertyRecord }) {
  const amenities = property.amenities ?? [];
  return (
    <Link
      href={`/dashboard/properties/${property.id}`}
      className="group overflow-hidden rounded-[1rem] border border-outline-variant bg-white shadow-soft transition-transform hover:-translate-y-1 hover:shadow-lg"
    >
      <div className="relative h-56 overflow-hidden">
        <img
          src={property.images?.[0] ?? '/images/property-1.svg'}
          alt={property.title}
          className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
      </div>
      <div className="space-y-3 p-5">
        <div className="flex items-center justify-between gap-4">
          <div>
            <h2 className="text-headline-sm font-semibold text-on-surface">{property.title}</h2>
            <p className="text-body-sm text-on-surface-variant">{property.location}</p>
          </div>
          <p className="text-headline-sm font-bold text-primary">₦{Number(property.price).toLocaleString()}</p>
        </div>
        <div className="flex flex-wrap gap-2">
          {amenities.slice(0, 3).map((amenity) => (
            <span key={amenity} className="rounded-full bg-surface-container-high px-3 py-1 text-label-sm text-on-surface-variant">
              {amenity}
            </span>
          ))}
        </div>
      </div>
    </Link>
  );
}

function StatsCard({ title, value }: { title: string; value: number }) {
  return (
    <div className="rounded-[1rem] bg-white p-5 shadow-soft border border-outline-variant">
      <p className="text-label-sm text-on-surface-variant">{title}</p>
      <p className="mt-3 text-headline-sm font-semibold text-primary">{value}</p>
    </div>
  );
}

export default async function DashboardPage({ searchParams }: DashboardPageProps) {
  const params = await searchParams;

  let properties: PropertyRecord[] = [];
  let error: string | null = null;
  try {
    properties = await getProperties(params);
  } catch (err) {
    error = err instanceof Error ? err.message : 'Failed to load properties.';
  }

  return (
    <div className="min-h-screen bg-background text-on-background">
      <TopAppBar title="Welcome back, Alex" showProfile={false} />
      <main className="mx-auto max-w-container-max px-margin-mobile py-stack-lg md:px-margin-desktop">
        <section className="mb-stack-lg">
          <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
            <div>
              <h2 className="text-headline-lg font-bold text-primary">Welcome back, {userSummary.name}</h2>
              <p className="text-body-md text-on-surface-variant">Discover homes near campus.</p>
            </div>
          </div>
        </section>

        <section className="mb-stack-lg grid gap-4 md:grid-cols-3">
          {quickActions.map((action) => (
            <StatsCard key={action.label} title={action.label} value={action.value} />
          ))}
        </section>

        <section className="mb-stack-lg">
          <Suspense fallback={null}>
            <SearchFilters />
          </Suspense>
        </section>

        {error ? (
          <div className="rounded-[1.5rem] border border-outline-variant bg-white p-10 text-center shadow-soft">
            <p className="text-headline-sm font-semibold text-on-surface">Something went wrong</p>
            <p className="mt-1 text-body-sm text-on-surface-variant">{error}</p>
          </div>
        ) : properties.length === 0 ? (
          <div className="rounded-[1.5rem] border border-outline-variant bg-white p-10 text-center shadow-soft">
            <p className="text-headline-sm font-semibold text-on-surface">No properties found</p>
            <p className="mt-1 text-body-sm text-on-surface-variant">Try adjusting your filters or check back later.</p>
          </div>
        ) : (
          <section className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {properties.map((property) => (
              <PropertyCard key={property.id} property={property} />
            ))}
          </section>
        )}
      </main>
    </div>
  );
}
